INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch07$PT159-S3-Q3$batch07$, 159, 3, 3, $batch07$Agree/Disagree$batch07$, $batch07$Anthropology professor: The new class I’m offering has been listed in the course catalog as a literature class, but it should be listed instead as an anthropology class. The texts we will study are all novels, but we will be examining them as sources of information about different cultures. Dean: The class is listed as it should be. All the readings in the class are works of literature.$batch07$, $batch07$The dialogue provides the most support for the claim that the anthropology professor and the dean disagree over whether$batch07$, $batch07$C$batch07$, true, $batch07$Batch 07; question text from local bank.$batch07$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT159-S3-Q3$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$A$batch07$, $batch07$all of the books that will be read in the new class are novels$batch07$, $batch07$Both Agree$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT159-S3-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$A$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$B$batch07$, $batch07$a class can be listed as both an anthropology class and a literature class$batch07$, $batch07$Out of Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT159-S3-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$B$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$C$batch07$, $batch07$the approach taken to the readings should be a crucial determinant of how a class is listed$batch07$, $batch07$Correct$batch07$, true FROM lr_questions q WHERE q.qid=$batch07$PT159-S3-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$C$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$D$batch07$, $batch07$the dean has the power to decide how a new class is to be listed$batch07$, $batch07$Out of Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT159-S3-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$D$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$E$batch07$, $batch07$an anthropology professor should be permitted to teach a literature class$batch07$, $batch07$Out of Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT159-S3-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$E$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT159-S3-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Professor's Position$batch07$, $batch07$The class should be listed as anthropology, not literature. The texts are novels, but the class studies them as sources about cultures.$batch07$), (1, $batch07$Dean's Position$batch07$, $batch07$The listing is right, because all the readings are works of literature.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$They agree on what is being read: novels, which are literature. The professor classifies by *how* the texts are studied. The dean classifies by *what* the texts are. So the clash is over which one should decide the listing.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether the approach to the readings should determine how the class is listed.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT159-S3-Q3$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$The professor says the texts "are all novels" and the dean says they're all works of literature.$batch07$), ($batch07$B$batch07$, $batch07$Neither speaker talks about listing a class under both departments.$batch07$), ($batch07$C$batch07$, $batch07$The professor: list it by approach (studying cultures). The dean: list it by content (literature). Whether approach is a crucial factor is exactly where they split.$batch07$), ($batch07$D$batch07$, $batch07$Neither speaker discusses who has the power to decide listings.$batch07$), ($batch07$E$batch07$, $batch07$Neither questions whether an anthropology professor may teach literature.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT159-S3-Q3$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
